class Solution { public:vector<int> findIndices(vector<int>& nums,int indexDifference,int valueDifference){int minValue=INT_MAX,maxValue=INT_MIN,minIndex=-1,maxIndex=-1;for(int j=indexDifference;j<(int)nums.size();++j){int candidate=j-indexDifference;if(nums[candidate]<minValue){minValue=nums[candidate];minIndex=candidate;}if(nums[candidate]>maxValue){maxValue=nums[candidate];maxIndex=candidate;}if(nums[j]-minValue>=valueDifference)return {minIndex,j};if(maxValue-nums[j]>=valueDifference)return {maxIndex,j};}return {-1,-1};} };
